import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.D8Tso2Ul.js";const u=JSON.parse('{"title":"Registro de una empresa","description":"","frontmatter":{},"headers":[],"relativePath":"guia-inicio/onboarding.md","filePath":"guia-inicio/onboarding.md"}'),i={name:"guia-inicio/onboarding.md"};function n(t,a,l,d,p,m){return r(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="registro-de-una-empresa" tabindex="-1">Registro de una empresa <a class="header-anchor" href="#registro-de-una-empresa" aria-label="Permalink to &quot;Registro de una empresa&quot;">​</a></h1><p>El <strong>registro</strong> (u onboarding) es el proceso por el cual una empresa nueva queda dada de alta en la plataforma. Al completarlo, la empresa tiene su espacio propio y un <strong>administrador</strong> listo para empezar a trabajar.</p><h2 id="que-se-necesita-para-registrar-una-empresa" tabindex="-1">Qué se necesita para registrar una empresa <a class="header-anchor" href="#que-se-necesita-para-registrar-una-empresa" aria-label="Permalink to &quot;Qué se necesita para registrar una empresa&quot;">​</a></h2><p>Para crear la cuenta de una empresa se piden algunos datos básicos:</p><ul><li><strong>Nombre / razón social</strong> de la empresa.</li><li><strong>RUT</strong> de la empresa.</li><li><strong>Cantidad de trabajadores</strong> (aproximada).</li><li><strong>Nombre y correo del administrador</strong> — la persona que gestionará la plataforma.</li></ul><h2 id="como-funciona" tabindex="-1">Cómo funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Cómo funciona&quot;">​</a></h2><ol><li>Se ingresan los datos de la empresa y de su administrador.</li><li>La plataforma <strong>crea el espacio de la empresa</strong> y la cuenta del administrador.</li><li>El administrador recibe sus <strong>credenciales de acceso</strong> (por correo).</li><li>La empresa queda <strong>activa</strong> y lista para operar.</li></ol><blockquote><p>✉️ El administrador recibirá un correo con su acceso inicial. Si no lo ves, revisa la carpeta de spam o correo no deseado.</p></blockquote><h2 id="primeros-pasos-del-administrador" tabindex="-1">Primeros pasos del administrador <a class="header-anchor" href="#primeros-pasos-del-administrador" aria-label="Permalink to &quot;Primeros pasos del administrador&quot;">​</a></h2><p>Una vez que la empresa está activa, el administrador debería:</p><ol><li><strong>Iniciar sesión</strong> y cambiar la contraseña temporal por una propia. Ver <a href="/manual/guia-inicio/instalacion.html">Cómo ingresar</a>.</li><li><strong>Revisar los datos de la empresa</strong>: logo, color, roles y cargos. Ver <a href="/manual/modulos/tenants.html">Mi Empresa</a>.</li><li><strong>Registrar a las personas</strong> del equipo. Ver <a href="/manual/modulos/personas.html">Personas</a>.</li><li><strong>Crear la primera obra</strong>. Ver <a href="/manual/modulos/obras.html">Obras</a>.</li></ol><p>Continúa con el recorrido completo en <a href="/manual/guia-inicio/primeros-pasos.html">Primeros pasos</a>.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Quién registra a mi empresa?</strong> El registro inicial lo realiza el equipo de la plataforma o el proceso de alta de tu proveedor. Una vez creada, tú como administrador gestionas todo desde dentro.</p><p><strong>No recibí el correo con mis credenciales.</strong> Revisa la carpeta de spam. Si aún no aparece, contacta al soporte de la plataforma para que reenvíen tu acceso.</p><p><strong>¿Puedo tener más de un administrador?</strong> Sí. Una vez dentro, el administrador puede registrar a otras personas y asignarles el rol de administrador desde el módulo de <a href="/manual/modulos/personas.html">Personas</a>.</p><p><strong>¿Los datos de mi empresa los puede ver otra empresa?</strong> No. Cada empresa opera en su propio espacio <strong>aislado</strong>: tus obras, personas y documentos solo los ve tu empresa.</p>',17)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
